sys_script_email.script:
/**
 * Prints an absolute URL to the reservation record.
 *
 * Built from gs.getProperty('glide.servlet.uri') rather than the ${URI} /
 * ${URI_REF} notification tokens so the link resolves correctly on every
 * instance (dev / test / prod) and renders as a real href instead of the
 * platform's own anchor markup.
 */
(function runMailScript(
    /* GlideRecord */ current,
    /* TemplatePrinter */ template,
    /* Optional EmailOutbound */ email,
    /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */ event,
) {
    var base = String(gs.getProperty('glide.servlet.uri') || '')
    if (base && base.charAt(base.length - 1) !== '/') {
        base += '/'
    }
    template.print(base + current.getTableName() + '.do?sys_id=' + current.getUniqueValue())
})(current, template, email, email_action, event);
